`timescale 1ns/1ps
import i2c4_pkg::*;

// -----------------------------------------------------------------------------
// Top integration template for Lattice Certus-NX LFD2NX-65-9BG484C.
//
// Important:
//   The real Lattice PCIe Endpoint IP wrapper is generated by Radiant.
//   Its module name and port names may differ by IP version and GUI setting.
//   This file keeps the PCIe IP instance as a commented template.  Connect the
//   generated PCIe Bridge Mode AXI-Lite master signals to axil_i2c4_regs below.
// -----------------------------------------------------------------------------
module pcie_i2c4_top #(
  parameter int CLK_DIV = 250
)(
  input  logic       refclk_p,
  input  logic       refclk_n,
  input  logic       perst_n,
  input  logic [0:0] pcie_rx_p,
  input  logic [0:0] pcie_rx_n,
  output logic [0:0] pcie_tx_p,
  output logic [0:0] pcie_tx_n,

  inout  wire  [3:0] i2c_scl,
  inout  wire  [3:0] i2c_sda,

  output logic [3:0] dev_irq
);

  // These signals should come from the generated Lattice PCIe Bridge Mode IP.
  logic        axil_clk;
  logic        axil_rst_n;
  logic [15:0] m_axi_awaddr;
  logic        m_axi_awvalid;
  logic        m_axi_awready;
  logic [31:0] m_axi_wdata;
  logic [3:0]  m_axi_wstrb;
  logic        m_axi_wvalid;
  logic        m_axi_wready;
  logic [1:0]  m_axi_bresp;
  logic        m_axi_bvalid;
  logic        m_axi_bready;
  logic [15:0] m_axi_araddr;
  logic        m_axi_arvalid;
  logic        m_axi_arready;
  logic [31:0] m_axi_rdata;
  logic [1:0]  m_axi_rresp;
  logic        m_axi_rvalid;
  logic        m_axi_rready;

  logic [3:0] i2c_scl_i;
  logic [3:0] i2c_sda_i;
  logic [3:0] i2c_scl_oen;
  logic [3:0] i2c_sda_oen;

  genvar gi;
  generate
    for (gi = 0; gi < 4; gi++) begin : g_i2c_od
      assign i2c_scl[gi] = i2c_scl_oen[gi] ? 1'bz : 1'b0;
      assign i2c_sda[gi] = i2c_sda_oen[gi] ? 1'bz : 1'b0;
      assign i2c_scl_i[gi] = i2c_scl[gi];
      assign i2c_sda_i[gi] = i2c_sda[gi];
    end
  endgenerate

  axil_i2c4_regs #(.CLK_DIV(CLK_DIV)) u_axil_i2c4_regs (
    .ACLK(axil_clk),
    .ARESETn(axil_rst_n),
    .S_AXI_AWADDR(m_axi_awaddr),
    .S_AXI_AWVALID(m_axi_awvalid),
    .S_AXI_AWREADY(m_axi_awready),
    .S_AXI_WDATA(m_axi_wdata),
    .S_AXI_WSTRB(m_axi_wstrb),
    .S_AXI_WVALID(m_axi_wvalid),
    .S_AXI_WREADY(m_axi_wready),
    .S_AXI_BRESP(m_axi_bresp),
    .S_AXI_BVALID(m_axi_bvalid),
    .S_AXI_BREADY(m_axi_bready),
    .S_AXI_ARADDR(m_axi_araddr),
    .S_AXI_ARVALID(m_axi_arvalid),
    .S_AXI_ARREADY(m_axi_arready),
    .S_AXI_RDATA(m_axi_rdata),
    .S_AXI_RRESP(m_axi_rresp),
    .S_AXI_RVALID(m_axi_rvalid),
    .S_AXI_RREADY(m_axi_rready),
    .i2c_scl_in(i2c_scl_i),
    .i2c_sda_in(i2c_sda_i),
    .i2c_scl_oen(i2c_scl_oen),
    .i2c_sda_oen(i2c_sda_oen),
    .dev_irq(dev_irq)
  );

  // ---------------------------------------------------------------------------
  // Replace this comment with the Radiant-generated PCIe Endpoint IP instance.
  // Conceptual connection:
  //   PCIe IP AXI-Lite Master  -> axil_i2c4_regs AXI-Lite Slave
  //
  // LMMI tie-off when dynamic config is unused:
  //   lmmi_request_i = 1'b0
  //   lmmi_wr_rdn_i  = 1'b0
  //   lmmi_offset_i  = '0
  //   lmmi_wdata_i   = '0
  //   lmmi outputs can be left unconnected if your generated wrapper allows it.
  // Always verify exact names/widths in the generated Radiant wrapper/example.
  // ---------------------------------------------------------------------------

endmodule
